const EMPTY = { CAT: {}, providers: [], REGIONS: [], TOTAL: 0, fmt: String }
const REG = {
  Europe: 612,
  'North America': 341,
  'Asia-Pacific': 298,
  'Latin America': 142,
  'Middle East': 96,
  Africa: 58,
  'Central Asia': 31,
  Caribbean: 22,
}
class Component extends DCLogic {
  state = { q: '', cat: 'all' }
  componentDidMount() {
    if (!RELAY)
      this._i = setInterval(() => {
        if (RELAY) {
          clearInterval(this._i)
          this.forceUpdate()
        }
      }, 40)
  }
  componentWillUnmount() {
    clearInterval(this._i)
  }
  renderVals() {
    const R = RELAY ?? EMPTY,
      S = this.state,
      q = S.q.trim().toLowerCase()
    const list = R.providers.filter(
      (p) =>
        (S.cat === 'all' || p.kind === S.cat) &&
        (!q || [p.name, p.hq, p.cat, p.railsText, p.licence].join(' ').toLowerCase().includes(q)),
    )
    const chip = (k, label, count) => ({
      kind: k,
      label,
      count,
      pick: () => this.setState({ cat: k }),
      bg: S.cat === k ? 'rgba(255,255,255,.07)' : 'transparent',
      fg: S.cat === k ? '#f7f8f8' : '#8a8f98',
      ring: S.cat === k ? 'inset 0 0 0 1px rgba(255,255,255,.14)' : 'inset 0 0 0 1px rgba(255,255,255,.07)',
    })
    const kinds = Object.keys(R.CAT)
    return {
      total: 'Live',
      q: S.q,
      onQ: (e) => this.setState({ q: e.target.value }),
      cats: [chip('all', 'All', 'Live'), ...kinds.map((k) => chip(k, R.CAT[k].label, ''))],
      rows: list
        .slice(0, 12)
        .map((p, i) => ({
          ...p,
          priceShort: p.price.split(' ')[0],
          blur: i >= 9 ? 'blur(3px)' : 'none',
          op: i >= 9 ? 0.6 : 1,
        })),
      moreLabel: list.length
        ? `Showing ${Math.min(9, list.length)} matching Providers. ${LAUNCH.seeAll}`
        : 'No Providers match that search yet.',
      regions: Object.entries(REG).map(([name]) => {
        const ps = R.providers.filter((p) => p.region === name)
        const mix = kinds.map((k) => ({ c: R.CAT[k].accent, f: Math.max(1, ps.filter((p) => p.kind === k).length) }))
        const top = ps
          .slice(0, 3)
          .map((p) => p.name)
          .join(', ')
        return { name, count: 'Multi-region', mix, top }
      }),
    }
  }
}

